def _shortest_paths(
    start: FieldId,
    outgoing: Dict[FieldId, List[FieldId]],
) -> Dict[FieldId, Tuple[FieldId, ...]]:
    """Shortest reference sequence from ``start`` to every field reachable
    along one or more edges.

    BFS discovers each field other than the seed via its lexicographically
    smallest shortest chain: fields on the same BFS level are enqueued in
    ascending full-name order, so a field's first-discovered parent starts
    the smallest node sequence. A self-loop or a longer cycle leading back
    to the seed also makes the seed reachable: its sequence is the shortest
    cycle (the smallest tree path to a field with an edge back to the
    seed, followed by the seed), ties broken lexicographically.
    """
    dist: Dict[FieldId, int] = {start: 0}
    parents: Dict[FieldId, FieldId] = {}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        for nxt in sorted(outgoing.get(current, ()), key=_full_name):
